// Offline AMCL 1.1.20 core experiment. No ROS initialization or publishers.
// Link AMCL 1.1.20 core libraries into a separate executable; never replace
// the installed AMCL node. Inputs are generated by atlas_extract_stationary_pf.py.
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <stdexcept>
#include <string>
#include <tuple>
#include <vector>
#include <nlohmann/json.hpp>
extern "C" {
#include "nav2_amcl/pf/pf.hpp"
#include "nav2_amcl/pf/pf_kdtree.hpp"
}
#include "nav2_amcl/sensors/laser/laser.hpp"

using json = nlohmann::json;
using Key = std::tuple<long long, long long, long long>;

void refresh_clusters(pf_t *pf) {
  auto *set = &pf->sets[pf->current_set];
  pf_kdtree_clear(set->kdtree);
  for (int i = 0; i < set->sample_count; ++i)
    pf_kdtree_insert(set->kdtree, set->samples[i].pose, set->samples[i].weight);
  pf_cluster_stats(pf, set);
}

void restore_prior(pf_t *pf, const json &prior) {
  auto *set = &pf->sets[pf->current_set];
  if (prior.empty() || prior.size() > static_cast<size_t>(pf->max_samples))
    throw std::runtime_error("invalid prior size");
  set->sample_count = prior.size();
  double total = 0;
  for (const auto &point : prior) total += point.at(3).get<double>();
  if (!(total > 0)) throw std::runtime_error("invalid prior weights");
  for (int i = 0; i < set->sample_count; ++i) {
    for (int axis = 0; axis < 3; ++axis)
      set->samples[i].pose.v[axis] = prior[i].at(axis).get<double>();
    set->samples[i].weight = prior[i].at(3).get<double>() / total;
  }
  pf->w_slow = pf->w_fast = 0;
  refresh_clusters(pf);
}

double ess(pf_sample_set_t *set) {
  double square_sum = 0, total = 0;
  for (int i = 0; i < set->sample_count; ++i) {
    total += set->samples[i].weight;
    square_sum += set->samples[i].weight * set->samples[i].weight;
  }
  return total * total / square_sum;
}

json measure(pf_t *pf) {
  auto *set = &pf->sets[pf->current_set];
  std::map<Key, double> support;
  for (int i = 0; i < set->sample_count; ++i) {
    const auto &s = set->samples[i];
    support[{llround(s.pose.v[0]*1e6), llround(s.pose.v[1]*1e6),
             llround(std::atan2(std::sin(s.pose.v[2]), std::cos(s.pose.v[2]))*1e6)}] += s.weight;
  }
  double squared = 0, total = 0;
  for (const auto &item : support) { squared += item.second * item.second; total += item.second; }
  int best = -1;
  double largest = -1;
  for (int i = 0; i < set->cluster_count; ++i) {
    if (set->clusters[i].weight > largest) { largest = set->clusters[i].weight; best = i; }
  }
  if (best < 0) throw std::runtime_error("no particle cluster");
  auto &cluster = set->clusters[best];
  return {{"particle_count", set->sample_count}, {"geometric_support", support.size()},
          {"geometric_ess", total*total/squared}, {"weight_ess", ess(set)},
          {"cluster_count", set->cluster_count}, {"winner_weight", largest},
          {"pose", {cluster.mean.v[0], cluster.mean.v[1], cluster.mean.v[2]}},
          {"xy_cov_trace", cluster.cov.m[0][0] + cluster.cov.m[1][1]}};
}

void fill_scan(nav2_amcl::LaserData &data, nav2_amcl::Laser &model, const json &scan) {
  data.laser = &model;
  data.range_count = scan.at("ranges").size();
  data.range_max = scan.at("range_max");
  data.ranges = new double[data.range_count][2];
  for (int i = 0; i < data.range_count; ++i) {
    data.ranges[i][0] = scan["ranges"][i];
    data.ranges[i][1] = scan["angle_min"].get<double>() + i * scan["angle_increment"].get<double>();
  }
}

double score_pose(nav2_amcl::Laser &model, const json &scan, const json &pose) {
  pf_t *one = pf_alloc(1, 1, 0, 0, nullptr);
  restore_prior(one, json::array({json::array({pose[0], pose[1], pose[2], 1.0})}));
  nav2_amcl::LaserData data;
  fill_scan(data, model, scan);
  model.sensorUpdate(one, &data);
  double score = one->w_slow;  // First update initializes average to actual likelihood.
  pf_free(one);
  return score;
}

json run(const json &bundle, map_t *map, const std::string &mode, int seed) {
  const auto &p = bundle.at("parameters");
  pf_t *pf = pf_alloc(p.at("min_particles"), p.at("max_particles"), 0, 0, nullptr);
  // pf_alloc calls srand48(time(NULL)); seed AFTER allocation for replayability.
  srand48(seed);
  pf->pop_err = p.at("pf_err"); pf->pop_z = p.at("pf_z");
  restore_prior(pf, bundle.at("particles"));
  nav2_amcl::LikelihoodFieldModel model(p.at("z_hit"), p.at("z_rand"), p.at("sigma_hit"),
      p.at("laser_likelihood_max_dist"), p.at("max_beams"), map);
  pf_vector_t laser_pose = {{bundle["laser"][0], bundle["laser"][1], 0.0}};
  model.SetLaserPose(laser_pose); // Yaw is already included in exported beam bearings.
  json first = measure(pf), previous = first, trajectory = json::array();
  double max_step = 0, max_shift = 0, max_heading = 0;
  int resamples = 0, jumps = 0;
  for (const auto &scan : bundle.at("scans")) {
    if (mode == "fixed_prior") restore_prior(pf, bundle.at("particles"));
    nav2_amcl::LaserData data;
    fill_scan(data, model, scan);
    if (!model.sensorUpdate(pf, &data)) throw std::runtime_error("sensor update failed");
    auto *set = &pf->sets[pf->current_set];
    if (mode == "baseline" || (mode == "ess_half" && ess(set) < .5 * set->sample_count)) {
      pf_update_resample(pf, nullptr); ++resamples;
    }
    refresh_clusters(pf);
    json current = measure(pf);
    const auto &pose = current["pose"];
    double step = std::hypot(pose[0].get<double>() - previous["pose"][0].get<double>(),
                            pose[1].get<double>() - previous["pose"][1].get<double>());
    double shift = std::hypot(pose[0].get<double>() - first["pose"][0].get<double>(),
                             pose[1].get<double>() - first["pose"][1].get<double>());
    double turn = pose[2].get<double>() - first["pose"][2].get<double>();
    max_heading = std::max(max_heading, std::abs(std::atan2(std::sin(turn), std::cos(turn))));
    max_step = std::max(max_step, step); max_shift = std::max(max_shift, shift);
    if (step > .5) ++jumps;
    current["time_s"] = scan["time_s"];
    trajectory.push_back(current); previous = current;
  }
  if (trajectory.empty()) throw std::runtime_error("no scans");
  const auto &last_scan = bundle["scans"].back();
  json result = {{"mode", mode}, {"seed", seed}, {"updates", trajectory.size()},
                 {"resamples", resamples}, {"jumps_over_0_5m", jumps}, {"max_step_m", max_step},
                 {"max_displacement_from_initial_m", max_shift},
                 {"max_heading_from_initial_deg", max_heading*180/M_PI},
                 {"initial", first}, {"final", previous},
                 {"last_scan_score_at_initial", score_pose(model, last_scan, first["pose"])},
                 {"last_scan_score_at_final", score_pose(model, last_scan, previous["pose"])},
                 {"trajectory", trajectory}};
  pf_free(pf);
  return result;
}

int main(int argc, char **argv) {
  try {
    if (argc != 3) throw std::runtime_error("usage: experiment bundle.json results.json");
    std::ifstream input(argv[1]); json bundle; input >> bundle;
    auto &grid = bundle.at("map");
    map_t *map = map_alloc();
    map->size_x = grid.at("width"); map->size_y = grid.at("height"); map->scale = grid.at("resolution");
    map->origin_x = grid["origin"][0].get<double>() + (map->size_x / 2)*map->scale;
    map->origin_y = grid["origin"][1].get<double>() + (map->size_y / 2)*map->scale;
    size_t count = static_cast<size_t>(map->size_x)*map->size_y;
    if (grid["cells"].size() != count) throw std::runtime_error("map size mismatch");
    map->cells = static_cast<map_cell_t *>(calloc(count, sizeof(map_cell_t)));
    for (size_t i = 0; i < count; ++i) {
      int value = grid["cells"][i]; map->cells[i].occ_state = value == 0 ? -1 : value == 100 ? 1 : 0;
    }
    json results = json::array();
    for (const std::string mode : {"baseline", "ess_half", "no_resample", "fixed_prior"})
      for (int seed : {1, 7, 42}) results.push_back(run(bundle, map, mode, seed));
    map_free(map);
    json output = {{"input", argv[1]}, {"window_offset_s", bundle["window_offset_s"]},
                   {"ground_truth", nullptr}, {"results", results},
                   {"limitations", "Zero-motion core experiment with published-cloud initialization and controlled RNG; not the original live AMCL checkpoint, full ROS replay, or production fix."}};
    std::ofstream out(argv[2]); out << output.dump(2) << std::endl;
    for (auto &r : results) { r.erase("trajectory"); std::cout << r.dump() << std::endl; }
  } catch (const std::exception &e) { std::cerr << e.what() << std::endl; return 1; }
}
